
import type { ImageRequest } from './ImageRequest.js';
import type { PostalAddress } from './PostalAddress.js';

export type UpdateMerchantRequest = { "address"?: PostalAddress; /** Set the merchant default to any supported API version. Omit to leave it unchanged. Null is not accepted. The default is shared across live and test environments; requests with Flint-Version use that header instead. */ "api_version"?: string; /** Business name buyers see. Surrounding whitespace is trimmed, and the result must have 1 to 120 characters. The name cannot be cleared, and only live credentials can set it. minLength: 1. maxLength: 120. */ "business_name"?: string; "email"?: string; /** Merchant profile version last read. A different current version returns MERCHANT_CHANGED. Send this value when saving a logo or icon to detect concurrent profile edits. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "expected_version"?: string; /** A square image, at least 128 by 128 pixels, shown where the store needs a small mark: browser tabs and compact headers. */ "icon"?: { /** maxLength: 512. */ "alt"?: string; /** Caller-owned identifier for this resource in an external system. minLength: 1. maxLength: 255. */ "external_reference_id"?: string; /** minLength: 1. maxLength: 8192. */ "source_url": string; }; "logo"?: ImageRequest; /** Caller-owned metadata. Omit this field to leave metadata unchanged. Send an object to merge by key, set a key to null to remove it, or set metadata to null to clear all metadata. An empty object makes no change. Empty strings are stored. Keys starting with flint_ are reserved and cannot be written through the public API. */ "metadata"?: Record<string, string | null> | null; "organization_id"?: string; "phone"?: string; "reporting_timezone"?: string; "support_email"?: string; /** Support phone in E.164 format, for example +12125551234. Send an empty string to clear the phone number. maxLength: 16. pattern: ^$|^\+[1-9][0-9]{6,14}$. */ "support_phone"?: string; "support_url"?: string; "website_url"?: string; };
